package vn.svframe.svframelib.script.condition.generic;import vn.svframe.svframelib.script.condition.RawCondition;import vn.svframe.svframelib.util.configobject.ConfigObject;public class StringContainsCondition extends RawCondition{public StringContainsCondition(ConfigObject c){super("string_contains"+render(c));}private static String render(ConfigObject c){if(c==null||c.getKeys().isEmpty())return "";StringBuilder b=new StringBuilder("{");boolean first=true;for(String k:c.getKeys()){if(!first)b.append(';');first=false;b.append(k).append('=').append(c.getString(k,""));}return b.append('}').toString();}}